fn compareSigned(a: i64, b: i64) Relation {
    return if (a < b) .LT else if (a > b) .GT else .EQ;
}
const Result = struct { pattern: u32, flags: u8 = 0 };
        const hidden = @as(u32, 1) << @intCast(m);
